/* WellStream Platform — Design System & Global Styles */
:root {
  --primary-navy: #0D1B2A;
  --secondary-navy: #1B2838;
  --dark-gray: #2A3444;
  --medium-gray: #3C424B;
  --light-gray: #8892A0;
  --text-primary: #E8ECF1;
  --text-secondary: #A0AAB8;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --accent-green: #6CC24A;
  --brand-navy: #15295A;
  --white: #FFFFFF;
  --danger: #E74C3C;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --container-width: 1200px;
  --header-height: 72px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.2);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.4);
  --transition: 0.3s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-family);
  background: var(--primary-navy);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-green); }

img { max-width: 100%; display: block; }

.container { max-width: var(--container-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,180,216,0.1);
  height: var(--header-height);
}
.nav-inner {
  max-width: var(--container-width);
  margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; justify-content: space-between;
  height: 100%;
}
.nav-logo {
  font-size: 1.4rem; font-weight: 700; color: var(--white);
  letter-spacing: -0.02em;
}
.nav-logo span { color: var(--accent-blue); }
.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a { color: var(--text-secondary); font-size: 0.9rem; font-weight: 500; transition: color var(--transition); }
.nav-links a:hover { color: var(--white); }

.nav-dropdown { position: relative; }
.nav-dropdown > a { cursor: pointer; display: flex; align-items: center; gap: 4px; }
.nav-dropdown > a::after {
  content: '';
  border: solid var(--text-secondary); border-width: 0 2px 2px 0;
  display: inline-block; padding: 2.5px;
  transform: rotate(45deg); transition: transform var(--transition);
  margin-top: -2px;
}
.nav-dropdown:hover > a::after { transform: rotate(-135deg); }
.dropdown-menu {
  position: absolute; top: calc(100% + 8px); left: -12px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius-md);
  min-width: 200px; padding: 8px 0;
  opacity: 0; visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition);
  box-shadow: var(--shadow-lg);
}
.nav-dropdown:hover .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: block; padding: 10px 20px; font-size: 0.875rem;
  color: var(--text-secondary); transition: all var(--transition);
}
.dropdown-menu a:hover { background: rgba(0,180,216,0.08); color: var(--white); }

.nav-cta {
  background: var(--accent-blue);
  color: var(--primary-navy) !important;
  padding: 10px 24px; border-radius: var(--radius-sm);
  font-weight: 600; font-size: 0.875rem;
  transition: all var(--transition);
}
.nav-cta:hover { background: var(--accent-green); color: var(--primary-navy) !important; transform: translateY(-1px); }

.mobile-toggle {
  display: none; background: none; border: none; cursor: pointer;
  flex-direction: column; gap: 5px; padding: 4px;
}
.mobile-toggle span {
  display: block; width: 24px; height: 2px;
  background: var(--text-primary); transition: all var(--transition);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 32px; border-radius: var(--radius-sm);
  font-weight: 600; font-size: 0.95rem;
  cursor: pointer; border: none;
  transition: all var(--transition); text-decoration: none;
}
.btn-primary {
  background: var(--accent-blue); color: var(--primary-navy);
}
.btn-primary:hover { background: var(--accent-green); color: var(--primary-navy); transform: translateY(-2px); box-shadow: var(--shadow-md); }
.btn-secondary {
  background: transparent; color: var(--accent-blue);
  border: 2px solid var(--accent-blue);
}
.btn-secondary:hover { background: var(--accent-blue); color: var(--primary-navy); transform: translateY(-2px); }
.btn-outline {
  background: transparent; color: var(--white);
  border: 1px solid rgba(255,255,255,0.3);
}
.btn-outline:hover { border-color: var(--accent-blue); color: var(--accent-blue); }

/* ===== HERO ===== */
.hero {
  padding: 160px 0 100px;
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, var(--primary-navy) 0%, var(--secondary-navy) 50%, #0a2540 100%);
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 70% 20%, rgba(0,180,216,0.08) 0%, transparent 60%),
              radial-gradient(ellipse at 30% 80%, rgba(108,194,74,0.05) 0%, transparent 50%);
}
.hero .container { position: relative; z-index: 1; }
.hero-label {
  display: inline-block;
  text-transform: uppercase; font-size: 0.75rem; font-weight: 700;
  letter-spacing: 3px; color: var(--accent-blue);
  margin-bottom: 20px;
  padding: 6px 16px;
  border: 1px solid rgba(0,180,216,0.3);
  border-radius: 20px;
}
.hero h1 {
  font-size: 3.2rem; font-weight: 800; line-height: 1.15;
  max-width: 700px; margin-bottom: 24px;
  background: linear-gradient(135deg, var(--white) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 1.15rem; color: var(--text-secondary);
  max-width: 560px; margin-bottom: 36px; line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== SECTION BASE ===== */
.section {
  padding: 100px 0;
  position: relative;
}
.section-alt { background: var(--secondary-navy); }
.section-label {
  text-transform: uppercase; font-size: 0.75rem; font-weight: 700;
  letter-spacing: 3px; color: var(--accent-blue);
  margin-bottom: 12px;
}
.section-title {
  font-size: 2.2rem; font-weight: 700; margin-bottom: 16px;
  color: var(--white);
}
.section-subtitle {
  font-size: 1.05rem; color: var(--text-secondary);
  max-width: 640px; line-height: 1.7;
}
.section-header { margin-bottom: 60px; }
.section-header.center { text-align: center; }
.section-header.center .section-subtitle { margin: 0 auto; }

/* ===== CARDS ===== */
.card {
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  padding: 32px; transition: all var(--transition);
}
.card:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.card-icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
  color: var(--accent-blue); font-size: 1.3rem;
}
.card h3 { font-size: 1.1rem; font-weight: 600; margin-bottom: 12px; color: var(--white); }
.card p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.6; }

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* ===== TABS ===== */
.tabs-nav {
  display: flex; gap: 4px;
  background: rgba(0,0,0,0.2);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 32px;
  overflow-x: auto;
}
.tab-btn {
  padding: 12px 24px;
  background: none; border: none;
  color: var(--text-secondary);
  font-family: var(--font-family);
  font-size: 0.9rem; font-weight: 500;
  cursor: pointer; border-radius: 6px;
  white-space: nowrap;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active {
  background: var(--accent-blue);
  color: var(--primary-navy);
  font-weight: 600;
}
.tab-panel { display: none; animation: fadeIn 0.4s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== ACCORDION ===== */
.accordion { max-width: 800px; }
.accordion-item {
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion-item:hover { border-color: rgba(0,180,216,0.25); }
.accordion-header {
  width: 100%; padding: 20px 24px;
  background: var(--secondary-navy);
  border: none; color: var(--white);
  font-family: var(--font-family);
  font-size: 1rem; font-weight: 600;
  cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
  transition: background var(--transition);
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-header::after {
  content: '+'; font-size: 1.4rem; color: var(--accent-blue);
  transition: transform var(--transition);
  font-weight: 300;
}
.accordion-item.open .accordion-header::after { content: '\2212'; }
.accordion-body {
  max-height: 0; overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.accordion-item.open .accordion-body {
  max-height: 400px; padding: 0 24px 20px;
}
.accordion-body p { color: var(--text-secondary); font-size: 0.95rem; line-height: 1.7; }

/* ===== STATS ===== */
.stats-grid { display: flex; gap: 48px; justify-content: center; flex-wrap: wrap; }
.stat-item { text-align: center; }
.stat-circle {
  width: 140px; height: 140px;
  border-radius: 50%;
  border: 4px solid rgba(0,180,216,0.2);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  margin: 0 auto 16px;
  position: relative;
  background: rgba(0,180,216,0.03);
}
.stat-circle::before {
  content: ''; position: absolute; inset: -4px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: var(--accent-blue);
  border-right-color: var(--accent-blue);
  animation: none;
}
.stat-value {
  font-size: 2.4rem; font-weight: 800;
  color: var(--accent-blue);
  line-height: 1;
}
.stat-suffix { font-size: 1.2rem; }
.stat-label {
  font-size: 0.85rem; color: var(--text-secondary);
  max-width: 160px; margin: 0 auto;
}

/* ===== TIMELINE ===== */
.timeline { max-width: 700px; margin: 0 auto; }
.timeline-item {
  display: flex; align-items: flex-start; gap: 24px;
  padding: 24px 0;
  border-bottom: 1px solid rgba(0,180,216,0.08);
}
.timeline-item:last-child { border-bottom: none; }
.timeline-duration {
  min-width: 120px; font-size: 1.3rem; font-weight: 700;
  color: var(--accent-blue); white-space: nowrap;
}
.timeline-content { flex: 1; }
.timeline-content p { color: var(--text-secondary); font-size: 0.95rem; margin-bottom: 12px; }
.progress-bar {
  height: 6px; background: rgba(0,180,216,0.15);
  border-radius: 3px; overflow: hidden;
}
.progress-fill {
  height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transition: width 1s ease;
}

/* ===== TESTIMONIALS ===== */
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex; transition: transform 0.5s ease;
}
.testimonial-card {
  min-width: 100%;
  padding: 40px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-lg);
}
.testimonial-card blockquote {
  font-size: 1.15rem; font-style: italic;
  color: var(--text-primary); line-height: 1.7;
  margin-bottom: 20px;
  position: relative;
  padding-left: 24px;
}
.testimonial-card blockquote::before {
  content: '\201C'; position: absolute; left: 0; top: -8px;
  font-size: 3rem; color: var(--accent-blue); font-style: normal;
  line-height: 1;
}
.testimonial-card cite {
  font-style: normal; font-size: 0.9rem;
  color: var(--accent-blue); font-weight: 600;
}
.carousel-dots {
  display: flex; justify-content: center; gap: 10px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: rgba(0,180,216,0.3);
  border: none; cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent-blue); transform: scale(1.2); }

/* ===== PLATFORM DIAGRAM ===== */
.diagram-container {
  max-width: 900px; margin: 0 auto;
  position: relative; padding: 48px 0;
}
.diagram-hub {
  width: 160px; height: 160px;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto;
  position: relative; z-index: 2;
  box-shadow: 0 0 40px rgba(0,180,216,0.3);
}
.diagram-hub span {
  color: var(--white); font-weight: 700;
  font-size: 0.95rem; text-align: center;
  line-height: 1.3;
}
.diagram-nodes {
  display: flex; justify-content: space-between;
  margin-top: -40px; position: relative;
  padding: 0 20px;
}
.diagram-node {
  flex: 1; text-align: center;
  padding: 32px 20px; max-width: 260px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius-md);
  position: relative;
  margin-top: 60px;
}
.diagram-node::before {
  content: '';
  position: absolute; top: -30px; left: 50%;
  width: 2px; height: 30px;
  background: linear-gradient(to bottom, var(--accent-blue), rgba(0,180,216,0.2));
}
.diagram-node h4 { color: var(--accent-blue); font-size: 0.95rem; margin-bottom: 8px; }
.diagram-node p { color: var(--text-secondary); font-size: 0.85rem; }

/* ===== FORM ===== */
.form-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 20px; max-width: 700px; margin: 0 auto;
}
.form-group { display: flex; flex-direction: column; }
.form-group.full-width { grid-column: 1 / -1; }
.form-group label {
  font-size: 0.85rem; font-weight: 500;
  color: var(--text-secondary); margin-bottom: 6px;
}
.form-group label .required { color: var(--accent-blue); }
.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px;
  background: rgba(0,0,0,0.2);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: var(--font-family);
  font-size: 0.95rem;
  transition: border-color var(--transition);
  outline: none;
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}
.form-group input.error,
.form-group select.error { border-color: var(--danger); }
.form-error {
  font-size: 0.8rem; color: var(--danger);
  margin-top: 4px; display: none;
}
.form-group textarea { resize: vertical; min-height: 100px; }
.form-submit { text-align: center; margin-top: 32px; }
.form-success {
  text-align: center; padding: 40px;
  display: none;
}
.form-success h3 { color: var(--accent-green); margin-bottom: 12px; }
.form-success p { color: var(--text-secondary); }

/* ===== BANNER ===== */
.banner {
  padding: 60px 0;
  background: linear-gradient(135deg, var(--accent-blue-dark), var(--accent-blue));
  position: relative; overflow: hidden;
}
.banner::before {
  content: ''; position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.banner .container { position: relative; z-index: 1; }
.banner h2 { color: var(--white); font-size: 1.6rem; margin-bottom: 12px; }
.banner p { color: rgba(255,255,255,0.85); margin-bottom: 24px; max-width: 600px; }
.banner .btn { background: var(--white); color: var(--accent-blue-dark); }
.banner .btn:hover { background: var(--primary-navy); color: var(--white); }

/* ===== FOOTER ===== */
.site-footer {
  background: #080F1A;
  border-top: 1px solid rgba(0,180,216,0.08);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 48px; margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; display: inline-block; }
.footer-brand p { color: var(--text-secondary); font-size: 0.85rem; max-width: 280px; line-height: 1.7; }
.footer-col h4 {
  font-size: 0.8rem; text-transform: uppercase;
  letter-spacing: 2px; color: var(--text-secondary);
  margin-bottom: 20px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { color: var(--light-gray); font-size: 0.875rem; }
.footer-col a:hover { color: var(--accent-blue); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.8rem; color: var(--light-gray); }
.footer-legal { display: flex; gap: 24px; }
.footer-legal a { font-size: 0.8rem; color: var(--light-gray); }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0;
  background: var(--secondary-navy);
  border-top: 1px solid rgba(0,180,216,0.15);
  padding: 20px 0; z-index: 9999;
  transform: translateY(0);
  transition: transform 0.5s ease;
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-inner {
  max-width: var(--container-width);
  margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center;
  justify-content: space-between; gap: 24px;
  flex-wrap: wrap;
}
.cookie-inner p { font-size: 0.875rem; color: var(--text-secondary); flex: 1; min-width: 280px; }
.cookie-actions { display: flex; gap: 12px; }
.cookie-actions .btn { padding: 10px 20px; font-size: 0.85rem; }

/* ===== SECURITY FEATURES LIST ===== */
.features-list { max-width: 800px; }
.feature-item {
  display: flex; gap: 20px; padding: 24px 0;
  border-bottom: 1px solid rgba(0,180,216,0.08);
}
.feature-item:last-child { border-bottom: none; }
.feature-icon {
  width: 44px; height: 44px; flex-shrink: 0;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
}
.feature-icon svg { width: 22px; height: 22px; stroke: var(--accent-blue); fill: none; stroke-width: 2; }
.feature-item h4 { color: var(--white); font-size: 1rem; margin-bottom: 6px; }
.feature-item p { color: var(--text-secondary); font-size: 0.9rem; }

/* ===== ETL BENEFITS ===== */
.benefits-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 24px; max-width: 800px;
}
.benefit-item {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 24px;
  background: rgba(0,180,216,0.03);
  border: 1px solid rgba(0,180,216,0.08);
  border-radius: var(--radius-md);
}
.benefit-check {
  width: 28px; height: 28px; flex-shrink: 0;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--accent-green); font-weight: 700; font-size: 0.85rem;
}
.benefit-item h4 { color: var(--white); font-size: 0.95rem; margin-bottom: 4px; }
.benefit-item p { color: var(--text-secondary); font-size: 0.85rem; }

/* ===== CULTURE SECTION ===== */
.culture-section {
  display: flex; align-items: center; gap: 64px;
}
.culture-content { flex: 1; }
.culture-visual {
  flex: 1; min-height: 320px;
  background: linear-gradient(135deg, rgba(0,180,216,0.1), rgba(108,194,74,0.1));
  border-radius: var(--radius-lg);
  display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(0,180,216,0.1);
  position: relative; overflow: hidden;
}
.culture-visual::before {
  content: '';
  position: absolute; width: 200px; height: 200px;
  border: 2px solid rgba(0,180,216,0.15);
  border-radius: 50%;
  animation: pulse-ring 3s ease-in-out infinite;
}
@keyframes pulse-ring {
  0%, 100% { transform: scale(0.8); opacity: 0.3; }
  50% { transform: scale(1.2); opacity: 0.6; }
}
.culture-visual .stat-highlight {
  text-align: center; position: relative; z-index: 1;
}
.culture-visual .stat-highlight .number {
  font-size: 3.5rem; font-weight: 800; color: var(--accent-blue);
  display: block;
}
.culture-visual .stat-highlight .label {
  color: var(--text-secondary); font-size: 0.95rem;
}

/* ===== RENEWABLES ===== */
.renewables-section {
  background: linear-gradient(135deg, #0a2a1a 0%, var(--primary-navy) 100%);
  border: 1px solid rgba(108,194,74,0.15);
  border-radius: var(--radius-lg);
  padding: 56px;
  display: flex; align-items: center; gap: 48px;
}
.renewables-section .section-title { color: var(--accent-green); }
.renewables-section .btn-primary { background: var(--accent-green); }
.renewables-section .btn-primary:hover { background: var(--accent-blue); }

/* ===== SUPPORT CONTACT ===== */
.support-grid {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 24px; max-width: 900px; margin: 0 auto;
}
.support-card {
  text-align: center; padding: 32px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
}
.support-card h4 { color: var(--accent-blue); margin-bottom: 8px; }
.support-card p { color: var(--text-secondary); font-size: 0.9rem; }

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  max-width: 900px; margin: 0 auto;
  display: flex; gap: 24px; align-items: stretch;
}
.lifecycle-phase {
  flex: 1;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.12);
  border-radius: var(--radius-md);
  padding: 28px 24px;
  position: relative;
  text-align: center;
}
.lifecycle-phase::after {
  content: '\2192'; position: absolute;
  right: -18px; top: 50%; transform: translateY(-50%);
  color: var(--accent-blue); font-size: 1.4rem;
  z-index: 1;
}
.lifecycle-phase:last-child::after { display: none; }
.lifecycle-phase h4 { color: var(--accent-blue); font-size: 0.95rem; margin-bottom: 8px; }
.lifecycle-phase p { color: var(--text-secondary); font-size: 0.82rem; }
.lifecycle-phase .phase-icon {
  width: 48px; height: 48px; margin: 0 auto 16px;
  background: rgba(0,180,216,0.1); border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.3rem;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero h1 { font-size: 2.6rem; }
  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .culture-section { flex-direction: column; gap: 40px; }
  .renewables-section { flex-direction: column; text-align: center; }
  .lifecycle-diagram { flex-direction: column; }
  .lifecycle-phase::after { content: '\2193'; right: auto; bottom: -18px; top: auto; left: 50%; transform: translateX(-50%); }
  .diagram-nodes { flex-direction: column; align-items: center; gap: 24px; }
  .diagram-node { margin-top: 30px; max-width: 100%; }
}

@media (max-width: 768px) {
  .hero { padding: 120px 0 70px; }
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .section { padding: 64px 0; }
  .section-title { font-size: 1.8rem; }
  .card-grid { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .stats-grid { gap: 32px; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .tabs-nav { flex-wrap: nowrap; overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--header-height);
    left: 0; right: 0;
    background: var(--primary-navy);
    padding: 24px;
    border-bottom: 1px solid rgba(0,180,216,0.1);
    gap: 16px;
  }
  .nav-links.open .nav-dropdown .dropdown-menu {
    position: static; opacity: 1; visibility: visible;
    transform: none; box-shadow: none;
    background: transparent; border: none;
    padding-left: 16px;
  }
  .mobile-toggle { display: flex; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .renewables-section { padding: 32px; }
  .timeline-item { flex-direction: column; gap: 8px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.7rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
  .stat-circle { width: 110px; height: 110px; }
  .stat-value { font-size: 1.8rem; }
}

/* WellStream Platform — Design System & Global Styles */
:root {
  --primary-navy: #0D1B2A;
  --secondary-navy: #1B2838;
  --dark-gray: #2A3444;
  --medium-gray: #3C424B;
  --light-gray: #8892A0;
  --text-primary: #E8ECF1;
  --text-secondary: #A0AAB8;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --accent-green: #6CC24A;
  --brand-navy: #15295A;
  --white: #FFFFFF;
  --danger: #E74C3C;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --container-width: 1200px;
  --header-height: 72px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.2);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.4);
  --transition: 0.3s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-family);
  background: var(--primary-navy);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-green); }

img { max-width: 100%; display: block; }

.container { max-width: var(--container-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,180,216,0.1);
  height: var(--header-height);
}
.nav-inner {
  max-width: var(--container-width);
  margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; justify-content: space-between;
  height: 100%;
}
.nav-logo {
  font-size: 1.4rem; font-weight: 700; color: var(--white);
  letter-spacing: -0.02em;
}
.nav-logo span { color: var(--accent-blue); }
.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a { color: var(--text-secondary); font-size: 0.9rem; font-weight: 500; transition: color var(--transition); }
.nav-links a:hover { color: var(--white); }

.nav-dropdown { position: relative; }
.nav-dropdown > a { cursor: pointer; display: flex; align-items: center; gap: 4px; }
.nav-dropdown > a::after {
  content: '';
  border: solid var(--text-secondary); border-width: 0 2px 2px 0;
  display: inline-block; padding: 2.5px;
  transform: rotate(45deg); transition: transform var(--transition);
  margin-top: -2px;
}
.nav-dropdown:hover > a::after { transform: rotate(-135deg); }
.dropdown-menu {
  position: absolute; top: calc(100% + 8px); left: -12px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius-md);
  min-width: 200px; padding: 8px 0;
  opacity: 0; visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition);
  box-shadow: var(--shadow-lg);
}
.nav-dropdown:hover .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: block; padding: 10px 20px; font-size: 0.875rem;
  color: var(--text-secondary); transition: all var(--transition);
}
.dropdown-menu a:hover { background: rgba(0,180,216,0.08); color: var(--white); }

.nav-cta {
  background: var(--accent-blue);
  color: var(--primary-navy) !important;
  padding: 10px 24px; border-radius: var(--radius-sm);
  font-weight: 600; font-size: 0.875rem;
  transition: all var(--transition);
}
.nav-cta:hover { background: var(--accent-green); color: var(--primary-navy) !important; transform: translateY(-1px); }

.mobile-toggle {
  display: none; background: none; border: none; cursor: pointer;
  flex-direction: column; gap: 5px; padding: 4px;
}
.mobile-toggle span {
  display: block; width: 24px; height: 2px;
  background: var(--text-primary); transition: all var(--transition);
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 32px; border-radius: var(--radius-sm);
  font-weight: 600; font-size: 0.95rem;
  cursor: pointer; border: none;
  transition: all var(--transition); text-decoration: none;
}
.btn-primary {
  background: var(--accent-blue); color: var(--primary-navy);
}
.btn-primary:hover { background: var(--accent-green); color: var(--primary-navy); transform: translateY(-2px); box-shadow: var(--shadow-md); }
.btn-secondary {
  background: transparent; color: var(--accent-blue);
  border: 2px solid var(--accent-blue);
}
.btn-secondary:hover { background: var(--accent-blue); color: var(--primary-navy); transform: translateY(-2px); }
.btn-outline {
  background: transparent; color: var(--white);
  border: 1px solid rgba(255,255,255,0.3);
}
.btn-outline:hover { border-color: var(--accent-blue); color: var(--accent-blue); }

/* ===== HERO ===== */
.hero {
  padding: 160px 0 100px;
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, var(--primary-navy) 0%, var(--secondary-navy) 50%, #0a2540 100%);
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 70% 20%, rgba(0,180,216,0.08) 0%, transparent 60%),
              radial-gradient(ellipse at 30% 80%, rgba(108,194,74,0.05) 0%, transparent 50%);
}
.hero .container { position: relative; z-index: 1; }
.hero-label {
  display: inline-block;
  text-transform: uppercase; font-size: 0.75rem; font-weight: 700;
  letter-spacing: 3px; color: var(--accent-blue);
  margin-bottom: 20px;
  padding: 6px 16px;
  border: 1px solid rgba(0,180,216,0.3);
  border-radius: 20px;
}
.hero h1 {
  font-size: 3.2rem; font-weight: 800; line-height: 1.15;
  max-width: 700px; margin-bottom: 24px;
  background: linear-gradient(135deg, var(--white) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 1.15rem; color: var(--text-secondary);
  max-width: 560px; margin-bottom: 36px; line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== SECTION BASE ===== */
.section {
  padding: 100px 0;
  position: relative;
}
.section-alt { background: var(--secondary-navy); }
.section-label {
  text-transform: uppercase; font-size: 0.75rem; font-weight: 700;
  letter-spacing: 3px; color: var(--accent-blue);
  margin-bottom: 12px;
}
.section-title {
  font-size: 2.2rem; font-weight: 700; margin-bottom: 16px;
  color: var(--white);
}
.section-subtitle {
  font-size: 1.05rem; color: var(--text-secondary);
  max-width: 640px; line-height: 1.7;
}
.section-header { margin-bottom: 60px; }
.section-header.center { text-align: center; }
.section-header.center .section-subtitle { margin: 0 auto; }

/* ===== CARDS ===== */
.card {
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  padding: 32px; transition: all var(--transition);
}
.card:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.card-icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
  color: var(--accent-blue); font-size: 1.3rem;
}
.card h3 { font-size: 1.1rem; font-weight: 600; margin-bottom: 12px; color: var(--white); }
.card p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.6; }

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* ===== TABS ===== */
.tabs-nav {
  display: flex; gap: 4px;
  background: rgba(0,0,0,0.2);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 32px;
  overflow-x: auto;
}
.tab-btn {
  padding: 12px 24px;
  background: none; border: none;
  color: var(--text-secondary);
  font-family: var(--font-family);
  font-size: 0.9rem; font-weight: 500;
  cursor: pointer; border-radius: 6px;
  white-space: nowrap;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active {
  background: var(--accent-blue);
  color: var(--primary-navy);
  font-weight: 600;
}
.tab-panel { display: none; animation: fadeIn 0.4s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== ACCORDION ===== */
.accordion { max-width: 800px; }
.accordion-item {
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion-item:hover { border-color: rgba(0,180,216,0.25); }
.accordion-header {
  width: 100%; padding: 20px 24px;
  background: var(--secondary-navy);
  border: none; color: var(--white);
  font-family: var(--font-family);
  font-size: 1rem; font-weight: 600;
  cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
  transition: background var(--transition);
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-header::after {
  content: '+'; font-size: 1.4rem; color: var(--accent-blue);
  transition: transform var(--transition);
  font-weight: 300;
}
.accordion-item.open .accordion-header::after { content: '\2212'; }
.accordion-body {
  max-height: 0; overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.accordion-item.open .accordion-body {
  max-height: 400px; padding: 0 24px 20px;
}
.accordion-body p { color: var(--text-secondary); font-size: 0.95rem; line-height: 1.7; }

/* ===== STATS ===== */
.stats-grid { display: flex; gap: 48px; justify-content: center; flex-wrap: wrap; }
.stat-item { text-align: center; }
.stat-circle {
  width: 140px; height: 140px;
  border-radius: 50%;
  border: 4px solid rgba(0,180,216,0.2);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  margin: 0 auto 16px;
  position: relative;
  background: rgba(0,180,216,0.03);
}
.stat-circle::before {
  content: ''; position: absolute; inset: -4px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: var(--accent-blue);
  border-right-color: var(--accent-blue);
  animation: none;
}
.stat-value {
  font-size: 2.4rem; font-weight: 800;
  color: var(--accent-blue);
  line-height: 1;
}
.stat-suffix { font-size: 1.2rem; }
.stat-label {
  font-size: 0.85rem; color: var(--text-secondary);
  max-width: 160px; margin: 0 auto;
}

/* ===== TIMELINE ===== */
.timeline { max-width: 700px; margin: 0 auto; }
.timeline-item {
  display: flex; align-items: flex-start; gap: 24px;
  padding: 24px 0;
  border-bottom: 1px solid rgba(0,180,216,0.08);
}
.timeline-item:last-child { border-bottom: none; }
.timeline-duration {
  min-width: 120px; font-size: 1.3rem; font-weight: 700;
  color: var(--accent-blue); white-space: nowrap;
}
.timeline-content { flex: 1; }
.timeline-content p { color: var(--text-secondary); font-size: 0.95rem; margin-bottom: 12px; }
.progress-bar {
  height: 6px; background: rgba(0,180,216,0.15);
  border-radius: 3px; overflow: hidden;
}
.progress-fill {
  height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transition: width 1s ease;
}

/* ===== TESTIMONIALS ===== */
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex; transition: transform 0.5s ease;
}
.testimonial-card {
  min-width: 100%;
  padding: 40px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-lg);
}
.testimonial-card blockquote {
  font-size: 1.15rem; font-style: italic;
  color: var(--text-primary); line-height: 1.7;
  margin-bottom: 20px;
  position: relative;
  padding-left: 24px;
}
.testimonial-card blockquote::before {
  content: '\201C'; position: absolute; left: 0; top: -8px;
  font-size: 3rem; color: var(--accent-blue); font-style: normal;
  line-height: 1;
}
.testimonial-card cite {
  font-style: normal; font-size: 0.9rem;
  color: var(--accent-blue); font-weight: 600;
}
.carousel-dots {
  display: flex; justify-content: center; gap: 10px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: rgba(0,180,216,0.3);
  border: none; cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent-blue); transform: scale(1.2); }

/* ===== PLATFORM DIAGRAM ===== */
.diagram-container {
  max-width: 900px; margin: 0 auto;
  position: relative; padding: 48px 0;
}
.diagram-hub {
  width: 160px; height: 160px;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto;
  position: relative; z-index: 2;
  box-shadow: 0 0 40px rgba(0,180,216,0.3);
}
.diagram-hub span {
  color: var(--white); font-weight: 700;
  font-size: 0.95rem; text-align: center;
  line-height: 1.3;
}
.diagram-nodes {
  display: flex; justify-content: space-between;
  margin-top: -40px; position: relative;
  padding: 0 20px;
}
.diagram-node {
  flex: 1; text-align: center;
  padding: 32px 20px; max-width: 260px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius-md);
  position: relative;
  margin-top: 60px;
}
.diagram-node::before {
  content: '';
  position: absolute; top: -30px; left: 50%;
  width: 2px; height: 30px;
  background: linear-gradient(to bottom, var(--accent-blue), rgba(0,180,216,0.2));
}
.diagram-node h4 { color: var(--accent-blue); font-size: 0.95rem; margin-bottom: 8px; }
.diagram-node p { color: var(--text-secondary); font-size: 0.85rem; }

/* ===== FORM ===== */
.form-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 20px; max-width: 700px; margin: 0 auto;
}
.form-group { display: flex; flex-direction: column; }
.form-group.full-width { grid-column: 1 / -1; }
.form-group label {
  font-size: 0.85rem; font-weight: 500;
  color: var(--text-secondary); margin-bottom: 6px;
}
.form-group label .required { color: var(--accent-blue); }
.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px;
  background: rgba(0,0,0,0.2);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: var(--font-family);
  font-size: 0.95rem;
  transition: border-color var(--transition);
  outline: none;
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}
.form-group input.error,
.form-group select.error { border-color: var(--danger); }
.form-error {
  font-size: 0.8rem; color: var(--danger);
  margin-top: 4px; display: none;
}
.form-group textarea { resize: vertical; min-height: 100px; }
.form-submit { text-align: center; margin-top: 32px; }
.form-success {
  text-align: center; padding: 40px;
  display: none;
}
.form-success h3 { color: var(--accent-green); margin-bottom: 12px; }
.form-success p { color: var(--text-secondary); }

/* ===== BANNER ===== */
.banner {
  padding: 60px 0;
  background: linear-gradient(135deg, var(--accent-blue-dark), var(--accent-blue));
  position: relative; overflow: hidden;
}
.banner::before {
  content: ''; position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.banner .container { position: relative; z-index: 1; }
.banner h2 { color: var(--white); font-size: 1.6rem; margin-bottom: 12px; }
.banner p { color: rgba(255,255,255,0.85); margin-bottom: 24px; max-width: 600px; }
.banner .btn { background: var(--white); color: var(--accent-blue-dark); }
.banner .btn:hover { background: var(--primary-navy); color: var(--white); }

/* ===== FOOTER ===== */
.site-footer {
  background: #080F1A;
  border-top: 1px solid rgba(0,180,216,0.08);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 48px; margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; display: inline-block; }
.footer-brand p { color: var(--text-secondary); font-size: 0.85rem; max-width: 280px; line-height: 1.7; }
.footer-col h4 {
  font-size: 0.8rem; text-transform: uppercase;
  letter-spacing: 2px; color: var(--text-secondary);
  margin-bottom: 20px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { color: var(--light-gray); font-size: 0.875rem; }
.footer-col a:hover { color: var(--accent-blue); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.8rem; color: var(--light-gray); }
.footer-legal { display: flex; gap: 24px; }
.footer-legal a { font-size: 0.8rem; color: var(--light-gray); }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0;
  background: var(--secondary-navy);
  border-top: 1px solid rgba(0,180,216,0.15);
  padding: 20px 0; z-index: 9999;
  transform: translateY(0);
  transition: transform 0.5s ease;
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-inner {
  max-width: var(--container-width);
  margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center;
  justify-content: space-between; gap: 24px;
  flex-wrap: wrap;
}
.cookie-inner p { font-size: 0.875rem; color: var(--text-secondary); flex: 1; min-width: 280px; }
.cookie-actions { display: flex; gap: 12px; }
.cookie-actions .btn { padding: 10px 20px; font-size: 0.85rem; }

/* ===== SECURITY FEATURES LIST ===== */
.features-list { max-width: 800px; }
.feature-item {
  display: flex; gap: 20px; padding: 24px 0;
  border-bottom: 1px solid rgba(0,180,216,0.08);
}
.feature-item:last-child { border-bottom: none; }
.feature-icon {
  width: 44px; height: 44px; flex-shrink: 0;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
}
.feature-icon svg { width: 22px; height: 22px; stroke: var(--accent-blue); fill: none; stroke-width: 2; }
.feature-item h4 { color: var(--white); font-size: 1rem; margin-bottom: 6px; }
.feature-item p { color: var(--text-secondary); font-size: 0.9rem; }

/* ===== ETL BENEFITS ===== */
.benefits-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 24px; max-width: 800px;
}
.benefit-item {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 24px;
  background: rgba(0,180,216,0.03);
  border: 1px solid rgba(0,180,216,0.08);
  border-radius: var(--radius-md);
}
.benefit-check {
  width: 28px; height: 28px; flex-shrink: 0;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--accent-green); font-weight: 700; font-size: 0.85rem;
}
.benefit-item h4 { color: var(--white); font-size: 0.95rem; margin-bottom: 4px; }
.benefit-item p { color: var(--text-secondary); font-size: 0.85rem; }

/* ===== CULTURE SECTION ===== */
.culture-section {
  display: flex; align-items: center; gap: 64px;
}
.culture-content { flex: 1; }
.culture-visual {
  flex: 1; min-height: 320px;
  background: linear-gradient(135deg, rgba(0,180,216,0.1), rgba(108,194,74,0.1));
  border-radius: var(--radius-lg);
  display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(0,180,216,0.1);
  position: relative; overflow: hidden;
}
.culture-visual::before {
  content: '';
  position: absolute; width: 200px; height: 200px;
  border: 2px solid rgba(0,180,216,0.15);
  border-radius: 50%;
  animation: pulse-ring 3s ease-in-out infinite;
}
@keyframes pulse-ring {
  0%, 100% { transform: scale(0.8); opacity: 0.3; }
  50% { transform: scale(1.2); opacity: 0.6; }
}
.culture-visual .stat-highlight {
  text-align: center; position: relative; z-index: 1;
}
.culture-visual .stat-highlight .number {
  font-size: 3.5rem; font-weight: 800; color: var(--accent-blue);
  display: block;
}
.culture-visual .stat-highlight .label {
  color: var(--text-secondary); font-size: 0.95rem;
}

/* ===== RENEWABLES ===== */
.renewables-section {
  background: linear-gradient(135deg, #0a2a1a 0%, var(--primary-navy) 100%);
  border: 1px solid rgba(108,194,74,0.15);
  border-radius: var(--radius-lg);
  padding: 56px;
  display: flex; align-items: center; gap: 48px;
}
.renewables-section .section-title { color: var(--accent-green); }
.renewables-section .btn-primary { background: var(--accent-green); }
.renewables-section .btn-primary:hover { background: var(--accent-blue); }

/* ===== SUPPORT CONTACT ===== */
.support-grid {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 24px; max-width: 900px; margin: 0 auto;
}
.support-card {
  text-align: center; padding: 32px;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
}
.support-card h4 { color: var(--accent-blue); margin-bottom: 8px; }
.support-card p { color: var(--text-secondary); font-size: 0.9rem; }

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  max-width: 900px; margin: 0 auto;
  display: flex; gap: 24px; align-items: stretch;
}
.lifecycle-phase {
  flex: 1;
  background: var(--secondary-navy);
  border: 1px solid rgba(0,180,216,0.12);
  border-radius: var(--radius-md);
  padding: 28px 24px;
  position: relative;
  text-align: center;
}
.lifecycle-phase::after {
  content: '\2192'; position: absolute;
  right: -18px; top: 50%; transform: translateY(-50%);
  color: var(--accent-blue); font-size: 1.4rem;
  z-index: 1;
}
.lifecycle-phase:last-child::after { display: none; }
.lifecycle-phase h4 { color: var(--accent-blue); font-size: 0.95rem; margin-bottom: 8px; }
.lifecycle-phase p { color: var(--text-secondary); font-size: 0.82rem; }
.lifecycle-phase .phase-icon {
  width: 48px; height: 48px; margin: 0 auto 16px;
  background: rgba(0,180,216,0.1); border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.3rem;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero h1 { font-size: 2.6rem; }
  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .culture-section { flex-direction: column; gap: 40px; }
  .renewables-section { flex-direction: column; text-align: center; }
  .lifecycle-diagram { flex-direction: column; }
  .lifecycle-phase::after { content: '\2193'; right: auto; bottom: -18px; top: auto; left: 50%; transform: translateX(-50%); }
  .diagram-nodes { flex-direction: column; align-items: center; gap: 24px; }
  .diagram-node { margin-top: 30px; max-width: 100%; }
}

@media (max-width: 768px) {
  .hero { padding: 120px 0 70px; }
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .section { padding: 64px 0; }
  .section-title { font-size: 1.8rem; }
  .card-grid { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .stats-grid { gap: 32px; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .tabs-nav { flex-wrap: nowrap; overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--header-height);
    left: 0; right: 0;
    background: var(--primary-navy);
    padding: 24px;
    border-bottom: 1px solid rgba(0,180,216,0.1);
    gap: 16px;
  }
  .nav-links.open .nav-dropdown .dropdown-menu {
    position: static; opacity: 1; visibility: visible;
    transform: none; box-shadow: none;
    background: transparent; border: none;
    padding-left: 16px;
  }
  .mobile-toggle { display: flex; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .renewables-section { padding: 32px; }
  .timeline-item { flex-direction: column; gap: 8px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.7rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
  .stat-circle { width: 110px; height: 110px; }
  .stat-value { font-size: 1.8rem; }
}

